import java.util.*;

class Solution {
  public int[] rearrangeBarcodes(int[] barcodes) {
    Map<Integer, Integer> frequencies = new HashMap<>();
    for (int barcode : barcodes) frequencies.merge(barcode, 1, Integer::sum);
    List<Integer> values = new ArrayList<>(frequencies.keySet());
    values.sort((a, b) -> Integer.compare(frequencies.get(b), frequencies.get(a)));
    int[] result = new int[barcodes.length];
    int position = 0;
    for (int value : values) {
      for (int count = frequencies.get(value); count > 0; count--) {
        if (position >= result.length) position = 1;
        result[position] = value;
        position += 2;
      }
    }
    return result;
  }
}
